/**
 * Generated by @break-change. Replace the scenario list with 5-10 adversarial
 * scenarios aimed at the current change. The defaults are a safe self-check so
 * the harness can be proven before it is pointed at a product change.
 *
 * Run it through the repository e2e lane:
 *   npm run verify -- e2e test/e2e/specs/break-change.<run>.e2e.ts
 *
 * The wrapper (`break-change.mjs run`) does that and removes this file. It also
 * exports BREAK_CHANGE_RUN_DIR, so scenario events land in the run report.
 */
import { appendFile, mkdir } from "node:fs/promises";
import path from "node:path";
import { $, browser, expect } from "@wdio/globals";
import { after, before, describe, it } from "mocha";

const RUN_ID = process.env.BREAK_CHANGE_RUN_ID ?? "__BREAK_CHANGE_RUN_ID__";
const OUT_DIR = path.resolve(process.env.BREAK_CHANGE_RUN_DIR ?? "__BREAK_CHANGE_OUT_DIR__");
const EVENTS_PATH = path.join(OUT_DIR, "events.jsonl");
const LIVE = process.env.BREAK_CHANGE_LIVE === "1";
const MAX_LIVE_TURNS = Number(process.env.BREAK_CHANGE_MAX_LIVE_TURNS ?? "0");
const ABSENT_COMMAND = "/break-change-absent-command";
const PROBE_NOTE = "Break Change Probe.md";

type ScriptedTurn = {
  label?: string;
  content: Array<Record<string, unknown>>;
  stopReason?: "stop" | "length" | "toolUse";
  delayMs?: number;
};

type Severity = "S1" | "S2" | "S3" | "S4";

type Scenario = {
  id: string;
  title: string;
  severity: Severity;
  expected: string;
  run: () => Promise<void>;
};

async function writeEvent(entry: Record<string, unknown>): Promise<void> {
  await mkdir(OUT_DIR, { recursive: true });
  await appendFile(EVENTS_PATH, `${JSON.stringify({ ts: new Date().toISOString(), runId: RUN_ID, ...entry })}\n`, "utf8");
}

/** Hard guard: live turns are opt-in and capped. Scripted turns need no key. */
function assertLiveBudget(): void {
  if (!LIVE) return;
  if (!Number.isInteger(MAX_LIVE_TURNS) || MAX_LIVE_TURNS < 1 || MAX_LIVE_TURNS > 3) {
    throw new Error("live break-change needs BREAK_CHANGE_MAX_LIVE_TURNS=1..3");
  }
}

async function openChat(): Promise<void> {
  await browser.executeObsidianCommand("agentic-chat:open-chat");
  await $(".agentic-chat-view").waitForExist();
}

/**
 * Scripted default. For a live scenario, replace this with a provider config
 * that reads AGENTIC_CHAT_API_KEY from the environment. Never print the key.
 */
async function configureScriptedProvider(): Promise<void> {
  const configured = await browser.executeObsidian(async ({ app }) => {
    const plugin = (
      app as unknown as {
        plugins?: {
          plugins?: Record<string, { settings?: Record<string, unknown>; saveSettings?: () => Promise<void> }>;
        };
      }
    ).plugins?.plugins?.["agentic-chat"];
    if (!plugin?.settings) return false;
    const settings = plugin.settings as Record<string, unknown> & {
      approval?: Record<string, unknown>;
      web?: Record<string, unknown>;
    };
    settings.provider = "openrouter";
    settings.openrouterApiKey = "e2e-scripted-key";
    settings.mode = "safe";
    settings.approval = { ...(settings.approval ?? {}), mutating: "ask", perTool: {} };
    settings.web = { ...(settings.web ?? {}), enabled: false };
    await plugin.saveSettings?.();
    return true;
  });
  if (!configured) throw new Error("agentic-chat plugin not found in the e2e sandbox");
}

async function installTurns(turns: ScriptedTurn[]): Promise<void> {
  await browser.execute((scriptedTurns) => {
    const target = window as typeof window & {
      __AGENTIC_CHAT_E2E_TURNS__?: ScriptedTurn[];
      __AGENTIC_CHAT_E2E_CALLS__?: number;
      __AGENTIC_CHAT_E2E_CALL_LOG__?: unknown[];
    };
    target.__AGENTIC_CHAT_E2E_TURNS__ = scriptedTurns;
    target.__AGENTIC_CHAT_E2E_CALLS__ = 0;
    target.__AGENTIC_CHAT_E2E_CALL_LOG__ = [];
  }, turns);
}

function textTurn(label: string, text: string): ScriptedTurn {
  return { label, stopReason: "stop", content: [{ type: "text", text }] };
}

async function sendPrompt(prompt: string): Promise<void> {
  await browser.execute((value) => {
    const textarea = document.querySelector<HTMLTextAreaElement>(".agentic-chat-input");
    const send = document.querySelector<HTMLButtonElement>(".agentic-chat-send");
    if (!textarea || !send) throw new Error("agentic-chat composer is not mounted");
    textarea.value = value;
    textarea.dispatchEvent(new Event("input", { bubbles: true }));
    send.click();
  }, prompt);
}

async function latestInfoText(): Promise<string> {
  await $(".agentic-chat-info").waitForExist();
  return await browser.execute(() => {
    const infos = Array.from(document.querySelectorAll<HTMLElement>(".agentic-chat-info"));
    return infos.at(-1)?.innerText ?? "";
  });
}

async function assistantText(): Promise<string> {
  const elements = await browser.$$(".agentic-chat-assistant .agentic-chat-text");
  const parts: string[] = [];
  for (const element of elements) parts.push(await element.getText());
  return parts.join("\n");
}

async function waitForNewAssistantText(previous: string): Promise<string> {
  let latest = previous;
  await browser.waitUntil(
    async () => {
      const streaming = await browser.execute(
        () => document.querySelectorAll(".agentic-chat-text.is-streaming").length > 0,
      );
      if (streaming) return false;
      const next = await assistantText();
      if (next.length <= previous.length) return false;
      const stable = next === latest;
      latest = next;
      return stable && next.trim().length > previous.trim().length;
    },
    { timeout: 15_000, interval: 500, timeoutMsg: "scripted assistant text did not render" },
  );
  return latest;
}

async function lastSentPrompt(): Promise<string | null> {
  return await browser.executeObsidian(async ({ app }, viewType) => {
    const view = app.workspace.getLeavesOfType(viewType)[0]?.view as unknown as {
      lastSentPrompt?: string | null;
    };
    return view?.lastSentPrompt ?? null;
  }, "agentic-chat-chat-view");
}

async function trashProbeNotes(): Promise<void> {
  await browser.executeObsidian(async ({ app, obsidian }, notePath) => {
    const file = app.vault.getAbstractFileByPath(notePath);
    if (file instanceof obsidian.TFile || file instanceof obsidian.TFolder) await app.vault.trash(file, true);
  }, PROBE_NOTE);
}

async function recordScenario(id: string, verdict: "PASS" | "FAIL", detail: string): Promise<void> {
  await writeEvent({ event: "scenario", id, verdict, detail });
}

/**
 * Replace or extend this list with 5-10 scenarios aimed at the changed
 * behavior. Good categories: removal, permission gate, empty input, state
 * persistence, reload, race, adjacent surviving behavior, docs/UI drift.
 */
const scenarios: Scenario[] = [
  {
    id: "S1",
    title: "A scripted chat turn reaches the transcript",
    severity: "S2",
    expected: "The assistant reply renders in the transcript.",
    run: async () => {
      const before = await assistantText();
      await sendPrompt("break-change probe turn");
      const after = await waitForNewAssistantText(before);
      expect(after).toContain("break-change scripted reply");
    },
  },
  {
    id: "S2",
    title: "An absent slash command is not in /help and is not handled locally",
    severity: "S2",
    expected: "The absent command is absent from /help; sending it falls through to the model instead of a local command.",
    run: async () => {
      await sendPrompt("/help");
      await $(".agentic-chat-info").waitForExist();
      const help = await latestInfoText();
      expect(help).toContain("Slash commands");
      expect(help).not.toContain("break-change-absent-command");

      const before = await assistantText();
      await sendPrompt(ABSENT_COMMAND);
      const after = await waitForNewAssistantText(before);
      expect(after).toContain("absent command reached the model");
      const sent = await lastSentPrompt();
      expect(sent ?? "").toContain("break-change-absent-command");
    },
  },
  {
    id: "S3",
    title: "/help still lists adjacent surviving commands",
    severity: "S3",
    expected: "/help lists /status and /doctor.",
    run: async () => {
      await sendPrompt("/help");
      await $(".agentic-chat-info").waitForExist();
      const help = await latestInfoText();
      for (const command of ["/status", "/doctor"]) expect(help).toContain(command);
    },
  },
  {
    id: "S4",
    title: "A hidden removed command is absent from /help and shows a removal notice",
    severity: "S2",
    expected: "/project is absent from /help, and /project renders the removal notice without a model call.",
    run: async () => {
      await sendPrompt("/help");
      await $(".agentic-chat-info").waitForExist();
      const help = await latestInfoText();
      expect(help).not.toContain("/project");

      await sendPrompt("/project");
      await browser.waitUntil(async () => (await latestInfoText()).includes("Removed"), {
        timeout: 5_000,
        timeoutMsg: "the removed /project command did not render its removal notice",
      });
    },
  },
  {
    id: "S5",
    title: "/status still opens the adjacent status panel",
    severity: "S3",
    expected: "The status panel renders provider and model details.",
    run: async () => {
      await sendPrompt("/status");
      await $(".agentic-chat-info").waitForExist();
      const status = await latestInfoText();
      expect(status).toContain("Provider");
    },
  },
];

describe("break-change exploratory scenarios", function () {
  this.timeout(180_000);

  before(async function () {
    assertLiveBudget();
    await configureScriptedProvider();
    // Install the queue before the chat view creates its service. The e2e
    // stream hook is captured at service creation, so a later install is too
    // late. Keep one text turn per scenario that sends a prompt.
    await installTurns([
      textTurn("S1", "break-change scripted reply"),
      textTurn("S2", "absent command reached the model"),
    ]);
    await trashProbeNotes();
    await openChat();
  });

  after(async function () {
    await trashProbeNotes();
    await browser.execute(() => {
      const target = window as typeof window & {
        __AGENTIC_CHAT_E2E_TURNS__?: unknown;
        __AGENTIC_CHAT_E2E_CALLS__?: number;
        __AGENTIC_CHAT_E2E_CALL_LOG__?: unknown[];
      };
      delete target.__AGENTIC_CHAT_E2E_TURNS__;
      delete target.__AGENTIC_CHAT_E2E_CALLS__;
      delete target.__AGENTIC_CHAT_E2E_CALL_LOG__;
    });
  });

  for (const scenario of scenarios) {
    it(`${scenario.id} ${scenario.title}`, async function () {
      await writeEvent({
        event: "scenario_start",
        id: scenario.id,
        title: scenario.title,
        severity: scenario.severity,
        expected: scenario.expected,
      });
      try {
        await scenario.run();
        await recordScenario(scenario.id, "PASS", scenario.expected);
      } catch (error) {
        await recordScenario(scenario.id, "FAIL", error instanceof Error ? error.message : String(error));
        throw error;
      }
    });
  }
});
